```java
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextInt();
        }

        Queue<Integer> q = new ArrayDeque<>();
        q.offer(0);
        long s = p[0]; // 第一段行驶

        for (int i = 1; i < n - 1; i++) {
            // 弹出不优的队首
            while (!q.isEmpty() && p[q.peek()] + i - q.peek() >= p[i]) {
                q.poll();
            }
            q.offer(i);
            s += p[q.peek()] + i - q.peek();
        }

        System.out.println(s);
    }
}
```

